async () => { /* W3 debrief: Lindqvist wrong_guilty, decided at the verdict, 'You already held what settled it: no personal device'; Okoro missed_guilty, Not named, decided at close; the no-blame line is the rule-misread one (it outranks 'worked out but not named', §6.3) */ const mg = window.MinigameFramework.currentMinigame; const d = mg.getTestState().board.debrief; const G = window.__test.getState().globals; const st = G.deduction_state;
  const card = id => d.cards.find(c => c.id === id);
  return G.deduction_outcome_ded_b_lindqvist === 'wrong_guilty' && st.verdicts.ded_b_lindqvist.decidedAtVerdict === true
    && /You already held what settled it: no personal device/.test(card('ded_b_lindqvist').text)
    && G.deduction_outcome_ded_b_okoro === 'missed_guilty' && /Not named/.test(card('ded_b_okoro').text)
    && d.noBlameCase === 'rule_misread' && !/You failed to/i.test(mg.container.textContent); }

async () => { /* W4 Finish: b_case_solved skipped, b_case_closed completed, b_wrong_name true, b_insider_named false, the success screen with its neutral text */ await new Promise(r => setTimeout(r, 1000)); const om = window.objectivesManager; const G = window.__test.getState().globals;
  return om.taskIndex.b_case_solved.status === 'skipped' && om.taskIndex.b_case_closed.status === 'completed' && G.b_wrong_name === true && G.b_insider_named === false
    && /Case closed/.test(document.body.textContent) && !/MISSION COMPLETE/.test(document.body.textContent); }
